function recentActivity(d) {
  const events=d.attempts.map(a=>({time:a.createdAt,title:d.disciplines.find(x=>x.id===a.disciplineId)?.title||'Avaliação',label:a.score==null?'Aguardando avaliação':a.score+'/10'}));
  for(const m of d.milestones||[]){
    if(!['guided_page','guided_recall'].includes(m.kind))continue;
    const doc=d.documents.find(x=>x.id===m.documentId);
    if(doc)events.push({time:m.updatedAt||m.createdAt,title:doc.title+' · p. '+m.page,label:m.kind==='guided_page'?'Leitura concluída':'Fixação respondida'});
  }
  events.sort((a,b)=>Date.parse(b.time)-Date.parse(a.time));
  return events.length?'<ul class="list">'+events.slice(0,5).map(e=>'<li>'+esc(e.title)+' · '+date(e.time)+' '+badge(e.label)+'</li>').join('')+'</ul>':empty('Seu histórico começa com a primeira atividade','Conclua uma página ou responda a uma questão para registrá-la aqui.');
}
const bibleBooks = {
  'gênesis':'gn','êxodo':'ex','salmos':'sl','salmo':'sl','isaías':'is','mateus':'mt','marcos':'mc','lucas':'lc',
  'joão':'jo','atos':'at','romanos':'rm','efésios':'ef','hebreus':'hb','tiago':'tg','apocalipse':'ap',
  'coríntios':'co','timóteo':'tm','pedro':'pe','gálatas':'gl','filipenses':'fp','colossenses':'cl'
};
function scriptureLinks(text) {
  const aliases = [...Object.keys(bibleBooks),...Object.values(bibleBooks)].join('|');
  const pattern = new RegExp('(?<![\\p{L}\\d])([123]?)\\s*('+aliases+')\\.?\\s+(\\d{1,3})\\s*[:,.]\\s*(\\d{1,3})(?:\\s*[-–]\\s*(\\d{1,3}))?(?!\\d)','giu');
  const refs = new Map();
  for (const match of text.matchAll(pattern)) {
    const [,prefix,book,chapter,verse,end] = match;
    const slug = prefix+(bibleBooks[book.toLowerCase()]||book.toLowerCase());
    const url = 'https://www.bibliaonline.com.br/ara/'+slug+'/'+chapter+'/'+verse+(end?'-'+end:'');
    refs.set(url,match[0].trim());
  }
  if (!refs.size) return '';
  return '<section><h3>Passagens citadas nesta página</h3><p class="small muted">Abrir na Bíblia Online (ARA), em outra aba.</p>'+[...refs].map(([url,label])=>'<a class="button" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>').join(' ')+'</section>';
}
function recallQueue(d) {
  const records = d.milestones || [];
  const visible = new Set(d.documents.filter(doc=>doc.status==='validated').map(doc=>doc.id));
  const key = row=>JSON.stringify([row.documentId,row.page]);
  const recalls = new Map(records.filter(row=>row.kind==='guided_recall').map(row=>[key(row),row]));
  const due = [...recalls.values()].filter(row=>Date.parse(row.dueAt)<=Date.now())
    .sort((a,b)=>Date.parse(a.dueAt)-Date.parse(b.dueAt));
  const fresh = new Map();
  for (const row of records) {
    if ((row.kind==='guided_page' || row.kind==='guided_reading') && !recalls.has(key(row))) fresh.set(key(row),row);
  }
  return [...due,...[...fresh.values()].sort((a,b)=>a.page-b.page)].filter(row=>visible.has(row.documentId));
}
async function guidedRecall(id,page) {
  const source=state.data.documents.find(d=>d.id===id);
  const passage=await api('/api/actions?route=study/guided',{method:'POST',data:{mode:'reread',documentId:id,page}});
  modal('Fixação da leitura','<p>'+esc(source.title)+' · p. '+esc(page)+'</p><label>Qual é a ideia central desta página e como você a explicaria a uma banca?<textarea id="guided-answer" maxlength="4000" required></textarea></label><details><summary>Conferir a leitura antes de se avaliar</summary><p style="white-space:pre-line">'+esc(passage.text)+'</p>'+scriptureLinks(passage.text)+'</details><p>Como foi sua resposta?</p><div class="row">'+['revisit','remembered'].map((result,i)=>button(i?'Consegui explicar':'Preciso revisar','record-recall','data-id="'+esc(id)+'" data-page="'+page+'" data-result="'+result+'"')).join('')+'</div>');
}
function dailyGuidePanel(d) {
  if (!d.dailyGuide) return '';
  const items = d.dailyGuide.blocks.map(block => {
    let action = '';
    if (block.documentId) action = button(block.pageDone?'Retomar leitura':'Começar leitura','guided-open','data-id="'+esc(block.documentId)+'"');
    if (block.library) action = button('Consultar a Bíblia','navigate','data-route="library"');
    if (block.review) {
      const next=recallQueue(d)[0];
      action=next?button('Revisar página '+next.page+' · '+d.documents.find(doc=>doc.id===next.documentId).title,'page-recall','data-id="'+esc(next.documentId)+'" data-page="'+next.page+'"'):button('Abrir revisões','guided-reviews');
    }
    return '<li><div class="row between"><strong>'+esc(block.focus)+'</strong>'+badge(block.minutes+' min')+'</div><p>'+esc(block.title)+'</p>'+(block.pageDone?'<p>Última página concluída: '+esc(block.pageDone)+'</p>':'')+action+'</li>';
  });
  return '<section class="panel"><h2>Seu roteiro de hoje</h2><p>'+esc(d.dailyGuide.totalMinutes)+' minutos de estudo</p><ol class="list">'+items.join('')+'</ol></section>';
}

async function openGuidedPage(id) {
  const source = state.data.documents.find(doc=>doc.id===id);
  const page = await api('/api/actions?route=study/guided',{method:'POST',data:{documentId:id}});
  if (page.finished) return modal(source.title,'<p>Você chegou ao final do texto disponível.</p>');
  modal(source.title,'<p>Página '+esc(page.page)+'</p><p class="muted">'+esc(page.section||'')+'</p><article id="guided-text" style="white-space:pre-line">'+esc(page.text)+'</article>'+scriptureLinks(page.text)+'<div class="row">'+('speechSynthesis' in window?button('Ouvir página','guided-listen')+button('Parar áudio','tts-stop'):'')+button('Concluir página e salvar posição','guided-save','data-id="'+esc(id)+'" data-page="'+esc(page.page)+'"',true)+'</div>');
}

const $=selector=>document.querySelector(selector);
const repair=value=>String(value??'');
const esc=value=>repair(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={data:null,route:'home',tab:'lessons',axis:'sistematica',session:null,lessonId:null,run:null,simulation:null,assistant:false};
let ttsUtterance=null;
const labels={home:'Início',study:'Estudar',assessments:'Avaliações',library:'Biblioteca',profile:'Meu perfil',admin:'Administração',journey:'Minha Jornada Ministerial'};
const statuses={draft:'Rascunho',ai_generated:'Gerado por IA',pending_review:'Aguardando revisão',in_review:'Em revisão',needs_changes:'Necessita de ajustes',rejected:'Reprovado',approved:'Aprovado',published:'Publicado',archived:'Arquivado',received:'Recebido',extracted:'Conferência pendente',validated:'Validado',needs_tools:'Extração pendente',processing:'Processando'};
const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',study:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3ZM12 5v17',assessments:'M9 4h6v4H9ZM6 6H4v16h16V6h-2M8 13h8M8 17h6',library:'M4 3h5v18H4ZM11 3h4v18h-4ZM17 4l4-1 3 17-4 1Z',profile:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 22v-3a8 8 0 0 1 16 0v3'};
const icon=name=>`<svg viewBox="0 0 25 25" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${icons[name]||icons.study}"/></svg>`;
const button=(text,action,attrs='',primary=false)=>`<button type="button" ${primary?'class="primary"':''} data-action="${action}" ${attrs}>${esc(text)}</button>`;
const badge=(text,green=false)=>`<span class="badge ${green?'green':''}">${esc(text)}</span>`;
const date=value=>value?new Date(value).toLocaleDateString('pt-BR'):'-';
const empty=(title,text,action='',actionLabel='Começar')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(text)}</p>${action?button(actionLabel,action):''}</div>`;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',6500);}
async function api(path,options={}){const {method='GET',data}=options;const headers={};if(method!=='GET'){headers['Content-Type']='application/json';if(state.csrf||state.data?.user.csrf)headers['X-CSRF-Token']=state.csrf||state.data.user.csrf;}const r=await fetch(path,{method,headers,body:data===undefined?undefined:JSON.stringify(data),credentials:'same-origin'});const value=await r.json().catch(()=>{throw new Error('O serviço está temporariamente indisponível. Tente novamente.');});if(!r.ok)throw new Error(value.error||'Não foi possível concluir.');return value;}
async function load(){state.data=await api('/api/state');state.csrf=state.data.user.csrf;}
async function init(){try{const auth=await api('/api/auth/session');state.csrf=auth.user?.csrf;const reset=new URL(location.href).searchParams.get('reset');if(reset)return renderAuth(auth,'reset');if(!auth.user)return renderAuth(auth,auth.setup?'register':'login');await load();if(!state.data.profile?.onboarded)state.route='onboarding';render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}catch(e){$('#app').innerHTML=empty('Conexão indisponível',e.message,'retry','Tentar novamente');}}
function renderAuth(auth,mode='login'){
  state.auth=auth;state.authMode=mode;
  const register=mode==='register',recover=mode==='recover',reset=mode==='reset';
  $('#app').innerHTML=`<div class="auth"><section class="auth-story"><a class="brand" href="/"><img src="/icon.svg" alt=""><strong>teo.</strong></a><div class="eyebrow" style="color:#c7d1b8">CONHECIMENTO QUE SE TORNA CONVICÇÃO</div><h1>Prepare-se com profundidade.<br>Sirva com clareza.</h1><p>Um espaço para estudar as Escrituras, amadurecer suas convicções e organizar sua preparação pastoral.</p></section><main class="auth-form" id="main"><div><div class="eyebrow">SEU ESPAÇO DE PREPARAÇÃO</div><h2>${register?'Comece sua jornada':recover?'Recupere o acesso':reset?'Defina uma nova senha':'Bem-vindo ao Teo'}</h2><p class="muted">${register?(auth.setup?'A primeira conta será administradora e estudante.':'Crie sua conta individual de estudo.'):'Seu assistente de preparação teológica e pastoral.'}</p><form id="auth-form">${register?'<label>Nome<input name="name" autocomplete="name" required maxlength="120"></label>':''}${!reset?'<label>E-mail<input type="email" name="email" autocomplete="email" required maxlength="254"></label>':''}${!recover?'<label>Senha<input type="password" name="password" autocomplete="'+(register||reset?'new-password':'current-password')+'" required minlength="12" maxlength="200"></label><p class="small muted">Use pelo menos 12 caracteres.</p>':''}${register&&auth.setup?'<label>Código de instalação<input name="bootstrap" required autocomplete="off"></label><p class="small muted">Disponível em data/bootstrap-code.txt no computador que executa o Teo.</p>':''}<div class="auth-error" id="auth-error" role="alert"></div><button class="primary">${register?'Criar minha conta':recover?'Solicitar recuperação':reset?'Atualizar senha':'Entrar'}</button></form><div class="row">${mode==='login'?button('Esqueci minha senha','auth-mode','data-mode="recover"'):button('Voltar ao login','auth-mode','data-mode="login"')}${mode==='login'&&(auth.setup||auth.publicSignup)?button('Criar conta','auth-mode','data-mode="register"'):''}</div></div></main></div>`;
  $('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button');btn.disabled=true;$('#auth-error').textContent='';try{const data=Object.fromEntries(new FormData(form));if(reset)data.token=new URL(location.href).searchParams.get('reset');const value=await api('/api/auth/'+mode,{method:'POST',data});if(recover){toast(value.message);return;}if(reset){history.replaceState({},'','/');toast('Senha atualizada. Entre novamente.');return renderAuth(auth,'login');}state.csrf=value.csrf;await load();state.route=state.data.profile.onboarded?'home':'onboarding';render();}catch(err){$('#auth-error').textContent=err.message;}finally{btn.disabled=false;}};
}
function shell(content){const d=state.data,p=d.profile;return `<aside class="sidebar"><a class="brand" href="/"><img src="/icon.svg" alt=""><strong>teo.</strong></a><p class="tagline">Preparação teológica<br>e pastoral</p><nav class="nav" aria-label="Navegação principal">${Object.keys(icons).map(key=>`<button data-action="navigate" data-route="${key}" class="${state.route===key?'active':''}" ${state.route===key?'aria-current="page"':''}>${icon(key)}${labels[key]}</button>`).join('')}</nav><div class="sidebar-foot"><p class="small muted">APRENDER · REFLETIR · SERVIR</p>${d.user.role==='admin'?button('Administração','navigate','data-route="admin"'):''}<div class="account"><span class="avatar">${esc(p.name?.slice(0,1).toUpperCase())}</span><div><strong class="small">${esc(p.name)}</strong><small>${d.user.role==='admin'?'Administrador e estudante':'Estudante'}</small></div></div></div></aside><main class="main" id="main"><header class="topbar"><a class="brand mobile-brand" href="/"><img src="/icon.svg" alt=""><strong>teo.</strong></a><span class="trail">Meu espaço / ${esc(labels[state.route]||'Preparação')}</span><div class="top-actions"><span class="small muted">${esc(new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'}))}</span>${button(document.body.classList.contains('dark')?'Modo claro':'Modo escuro','theme','class="quiet"')}${button('Falar com Teo','assistant','class="quiet"')}</div></header>${content}</main>${state.route!=='onboarding'?`<button aria-label="Perguntar ao Teo" class="primary floating-teo" data-action="assistant"><img src="/icon.svg" alt="">Perguntar ao Teo</button>`:''}`;}
function render(){document.body.classList.toggle('reading-mode',state.readingMode===true);const views={home:home,study:study,assessments:assessments,library:library,profile:profile,admin:admin,journey:journey,onboarding:onboarding};$('#app').innerHTML=shell((views[state.route]||home)());bindForms();if(state.route==='study'&&state.lessonId)bindReading();if(state.route==='journey')loadJourney();}
function intro(eyebrow,title,text){return `<section class="intro"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(text)}</p></section>`;}
function home(){const d=state.data,lessons=d.lessons.filter(l=>l.status==='published'),done=d.progress.filter(p=>p.completed).length,percent=lessons.length?Math.round(done/lessons.length*100):0,seconds=d.sessions.reduce((sum,s)=>sum+s.activeSeconds,0);const diagnostic=d.milestones.find(x=>x.kind==='diagnostic'),next=lessons.find(l=>!d.progress.some(p=>p.lessonId===l.id&&p.completed)),reviews=d.mastery.filter(m=>m.dueAt&&Date.parse(m.dueAt)<=Date.now());
  return `${intro('SUA JORNADA, UM DIA DE CADA VEZ',`Olá, ${d.profile.name.split(' ')[0]}.`,'Conhecimento sólido se constrói com constância, boas perguntas e tempo nas Escrituras.')}${dailyGuidePanel(d)}<div class="hero-grid"><section class="panel accent"><div class="eyebrow">${diagnostic?'SEU PRÓXIMO PASSO':'COMECE PELO DIAGNÓSTICO'}</div><h2>${diagnostic?(next?esc(next.title):'Seu espaço está pronto para crescer.'):'Conheça seu ponto de partida.'}</h2><p class="muted">${diagnostic?(next?'Retome o estudo e transforme leitura em compreensão.':'Aguarde novas materiais de estudo aprovadas ou revise o que já estudou.'):'Uma avaliação dos quatro eixos ajuda a orientar a preparação além da sua autoavaliação.'}</p>${diagnostic?(next?button('Iniciar sessão','open-lesson',`data-id="${next.id}"`):button('Explorar currículo','navigate','data-route="study"')):button('Fazer diagnóstico','start-diagnostic')}</section><section class="panel"><div class="eyebrow">PREPARAÇÃO ATÉ O CONCÍLIO</div><div class="row between"><span class="metric">${percent}<small>%</small></span>${badge(diagnostic?'Preparação':'Diagnóstico',true)}</div><div class="bar" role="progressbar" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100" aria-label="Material de estudos concluídas"><span style="width:${percent}%"></span></div><p class="small muted">${done} de ${lessons.length} materiais publicados concluídas.</p><p class="small">${esc(d.plan.notice)}</p></section></div><div class="grid four"><section class="panel"><div class="eyebrow">ROTINA DIÁRIA</div><div class="metric">${d.preferences?.minutes||30}<small> min</small></div><span class="small muted">${d.preferences?.days?.length||0} dias por semana</span></section><section class="panel"><div class="eyebrow">ESTUDO ATIVO</div><div class="metric">${Math.floor(seconds/60)}<small> min</small></div><span class="small muted">Tempo registrado</span></section><section class="panel"><div class="eyebrow">AVALIAÇÕES</div><div class="metric">${d.attempts.length}</div><span class="small muted">Tentativas salvas</span></section><section class="panel"><div class="eyebrow">REVISÕES</div><div class="metric">${reviews.length}</div><span class="small muted">Disciplinas para hoje</span></section></div><div class="grid"><section><div class="section-head"><h2>Seu domínio por eixo</h2>${badge('Avaliação ? leitura')}</div><div class="panel">${d.axes.map(axis=>{const ds=d.disciplines.filter(x=>x.axisId===axis.id).map(x=>x.id),ms=d.mastery.filter(m=>ds.includes(m.disciplineId)),score=ms.length?ms.reduce((sum,x)=>sum+x.score,0)/ms.length:null;return `<div class="chart-row"><div class="row"><span>${esc(axis.title)}</span><strong>${score===null?'Sem avaliação':score.toFixed(1)+'/10'}</strong></div><div class="bar"><span style="width:${score===null?0:score*10}%"></span></div></div>`;}).join('')}</div></section><section><div class="section-head"><h2>Próximas revisões</h2>${button('Ver avaliações','navigate','data-route="assessments" class="link"')}</div><div class="panel">${d.mastery.length?`<ul class="list">${[...d.mastery].sort((a,b)=>Date.parse(a.dueAt)-Date.parse(b.dueAt)).slice(0,4).map(m=>`<li><div class="row between"><strong>${esc(d.disciplines.find(x=>x.id===m.disciplineId)?.title)}</strong>${badge(date(m.dueAt))}</div><span class="small muted">Domínio demonstrado: ${m.score.toFixed(1)}/10</span></li>`).join('')}</ul>`:empty('Revisões no momento certo','Ao responder às questões, suas revisões serão organizadas em D+1, D+3, D+7 e D+14.')}</div></section></div><div class="section-head"><h2>Jornada de preparação</h2>${button('Minha jornada ministerial','navigate','data-route="journey" class="link"')}</div><div class="panel"><div class="row between"><div><strong>${d.plan.hours?d.plan.hours+' horas estimadas':'Carga horária ainda não estimada'}</strong><p class="muted small">${d.plan.hours?`${d.plan.sessions} sessões · ${d.plan.weeks} semanas`+(d.plan.completionDate?' · '+date(d.plan.completionDate):''):'Consulte o roteiro de hoje para ver as leituras disponíveis.'}</p></div>${badge(d.eligibility.eligible?'Simulação disponível':'Simulação em preparação',d.eligibility.eligible)}</div>${d.eligibility.reasons.length?`<ul class="small muted">${d.eligibility.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:''}<p class="small muted">${d.plan.hours?'A estimativa acompanha seu avanço.':''}</p></div><div class="section-head"><h2>Atividade recente</h2></div><div class="panel">${recentActivity(d)}</div>`;}
function study(){if(state.lessonId)return reader();const d=state.data;return `${intro('FORMAÇÃO COM FUNDAMENTO','Um currículo para aprofundar.','Três eixos de conhecimento e uma camada transversal de preparação ministerial. Conteúdos entram na jornada após revisão e publicação.')}<div class="tabs" role="tablist">${d.axes.map(a=>button(a.title,'axis',`data-id="${a.id}" class="${state.axis===a.id?'active':''}"`)).join('')}</div><div class="notice">${esc(d.axes.find(a=>a.id===state.axis)?.description||'')}</div><div class="panel">${d.disciplines.filter(x=>x.axisId===state.axis).map((discipline,i)=>{const lessons=d.lessons.filter(l=>l.disciplineId===discipline.id&&l.status==='published');return `<div class="discipline"><details><summary><span class="small muted">${String(i+1).padStart(2,'0')}</span>${esc(discipline.title)}<span class="badge">${lessons.length} materiais de estudo</span></summary>${lessons.length?lessons.map(l=>{const p=d.progress.find(p=>p.lessonId===l.id);return `<div class="lesson-row"><div><strong>${esc(l.title)}</strong><div class="small muted">${esc(d.modules.find(m=>m.id===l.moduleId)?.title||'Módulo')} · ${l.estimatedMinutes||30} min · ${p?.completed?'Concluída':p?.studied?'Estudada':'A estudar'}</div></div>${button('Estudar','open-lesson',`data-id="${l.id}"`)}</div>`;}).join(''):empty('Conteúdo em preparação','As materiais de estudo desta disciplina ainda não foram publicadas.')}</details></div>`;}).join('')}</div><div class="section-head"><h2>Suas anotações</h2></div><div class="panel">${d.notes.length?d.notes.map(n=>`<div class="discipline"><p>${esc(n.text)}</p>${n.quote?`<blockquote class="muted">${esc(n.quote)}</blockquote>`:''}${button('Excluir','delete-note',`data-id="${n.id}" class="quiet danger"`)}</div>`).join(''):empty('Guarde suas reflexões','Durante a leitura, selecione um trecho e escolha Anotar.')}</div>`;}
function references(refs=[]){return `<div class="row">${refs.map(r=>`<a class="small" href="https://www.bibliaonline.com.br/busca?q=${encodeURIComponent(r)}" target="_blank" rel="noopener noreferrer">${esc(r)} ↗</a>`).join('')}</div>`;}
function reader(){const d=state.data,l=d.lessons.find(x=>x.id===state.lessonId);if(!l)return empty('Material de estudo indisponível','Volte ao currículo.','back-study','Ver currículo');const fav=d.favorites.some(x=>x.targetId===l.id);const qs=d.questions.filter(q=>q.lessonId===l.id);return `<div class="reader"><div class="toolbar">${button(' Currículo','back-study','class="quiet"')}${button('A-','font-smaller','aria-label="Diminuir fonte"')}${button('A+','font-larger','aria-label="Aumentar fonte"')}${button('Modo leitura','reading-mode')}${button(fav?'Favoritado':'Favoritar','favorite',`data-id="${l.id}"`)}${button('Anotar trecho','annotate')}${'speechSynthesis'in window?`<span class="tts-controls">${button('Narrar material de estudo','tts-start')}${button('Pausar','tts-pause','class="quiet"')}${button('Continuar','tts-resume','class="quiet"')}${button('Parar','tts-stop','class="quiet"')}</span>`:''}</div><article id="lesson-text"><div class="eyebrow" style="margin-top:28px">${esc(d.disciplines.find(x=>x.id===l.disciplineId)?.title)} · CONTEÚDO OFICIAL REVISADO</div><h1>${esc(l.title)}</h1><p>${esc(l.introduction)}</p><h2>Objetivos de aprendizagem</h2><ul>${(l.objectives||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${(l.topics||[]).map((t,i)=>`<section id="topic-${i}"><h2>${esc(t.title)}</h2><p>${esc(t.text)}</p></section>`).join('')}<h2>Fundamentação bíblica</h2>${references(l.biblicalReferences)}<h2>Contexto das passagens</h2><p>${esc(l.context)}</p><h2>Texto e doutrina</h2><p>${esc(l.doctrinalRelation)}</p><h2>Conclusão</h2><p>${esc(l.conclusion)}</p><h2>Para refletir</h2><ol>${(l.fixation||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${l.activity?`<h2>Atividade discursiva</h2><p>${esc(l.activity)}</p>`:''}</article><div class="section-head"><h2>Atividades da material de estudo</h2></div><div id="lesson-questions">${qs.length?qs.map(q=>questionForm(q)).join(''):empty('Atividades não disponíveis','A administração precisa publicar as atividades essenciais.')}</div><div class="notice">Concluir uma material de estudo registra a sessão. O domínio é demonstrado pelas avaliações. O tempo de leitura pausa após inatividade.</div><div class="row">${button('Concluir sessão','complete-study','',true)}${button('Perguntar sobre esta material de estudo','assistant')}</div><p class="small muted" id="study-clock">Registrando tempo ativo.</p><div class="section-head"><h2>Fontes da material de estudo</h2></div><div class="panel">${(l.sourceIds||[]).map(id=>button('Ver fragmento '+id.slice(0,8),'source-by-id',`data-id="${id}" class="link"`)).join(' · ')}<p class="small muted">Versão ${l.version} · Revisão aprovada em ${date(l.approvedAt)}</p></div></div>`;}
function assessments(){const d=state.data;if(state.run)return `${intro('DIAGNÓSTICO INICIAL','Seu ponto de partida.','Responda com o conhecimento que você tem hoje. A avaliação ajuda a direcionar o estudo.')}<div class="panel">${state.run.questions.map(q=>questionForm(q,true)).join('')}${button('Concluir diagnóstico','submit-diagnostic','',true)}</div>`;if(state.simulation)return simulationView();const tab=state.assessmentTab||'practice';return `${intro('COMPREENSÃO DEMONSTRADA','Avalie. Revise. Consolide.','Respostas, notas e revisões formam um histórico real da sua aprendizagem.')}<div class="tabs">${[['practice','Praticar'],['reviews','Revisões'],['history','Histórico'],['simulation','Simulação de concílio']].map(([id,label])=>button(label,'assessment-tab',`data-id="${id}" class="${tab===id?'active':''}"`)).join('')}</div>${tab==='practice'?`<div class="row between"><p class="muted">${d.questions.length} questões publicadas.</p>${button('Diagnóstico inicial','start-diagnostic')}</div>${d.questions.length?`<div class="panel">${d.questions.map(q=>questionForm(q)).join('')}</div>`:empty('Banco de questões em preparação','A administração pode criar ou importar perguntas, aprová-las e publicá-las.')}`:''}${tab==='reviews'?`<div class="panel">${d.mastery.length?d.mastery.map(m=>`<div class="discipline row between"><div><strong>${esc(d.disciplines.find(x=>x.id===m.disciplineId)?.title)}</strong><p class="small muted">Próxima revisão: ${date(m.dueAt)} · Domínio ${m.score}/10</p></div>${button('Revisar','review-discipline',`data-id="${m.disciplineId}"`)}</div>`).join(''):empty('Suas revisões aparecerão aqui','Responda às primeiras atividades para iniciar o ciclo de revisão.')}</div>`:''}${tab==='history'?`<div class="panel">${d.attempts.length?d.attempts.slice().reverse().map(a=>`<div class="discipline"><div class="row between"><strong>${esc(d.questions.find(q=>q.id===a.questionId)?.text||'Tentativa registrada')}</strong>${badge(a.score===null?'Sem nota':a.score+'/10',a.score>=7)}</div><p class="small muted">${date(a.createdAt)} · ${a.aiEvaluation?'Avaliação interna por IA':'Avaliação objetiva ou pendente'}</p><p>${esc(typeof a.answer==='string'?a.answer:JSON.stringify(a.answer))}</p>${a.feedback?feedback(a):a.score===null?button('Avaliar com IA','evaluate-attempt',`data-id="${a.id}"`):''}</div>`).join(''):empty('Histórico ainda vazio','As tentativas permanecem disponíveis para acompanhar sua evolução.')}</div>`:''}${tab==='simulation'?simulationSetup():''}`;}
function feedback(a){const f=a.feedback||{};return `<div class="feedback"><strong>Avaliação interna do Teo · ${a.score}/10</strong>${a.grade?`<p class="small">Teologia: ${a.grade.theological} · Fundamentação: ${a.grade.biblical??'Não exigida'} · Clareza: ${a.grade.clarity}</p>`:''}${[['strengths','Pontos fortes'],['errors','Erros conceituais'],['omissions','Omissões']].map(([k,title])=>Array.isArray(f[k])&&f[k].length?`<h4>${title}</h4><ul>${f[k].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'').join('')}${f.modelAnswer?`<details><summary>Resposta-modelo</summary><p>${esc(f.modelAnswer)}</p></details>`:''}<p>${esc(f.recommendation||'')}</p>${references(f.references)}${sourceList(f.citations||[])}</div>`;}
function simulationSetup(){const d=state.data;return `<div class="grid"><section class="panel"><h2>Uma pergunta por vez.</h2><p class="muted">Sem dicas antes da resposta. As notas discursivas dependem de um provedor de IA autorizado e de fontes validadas.</p>${d.eligibility.reasons.length?`<ul class="small">${d.eligibility.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:badge('Critérios de liberação atingidos',true)}<form id="simulation-form"><div class="form-grid"><label>Quantidade<input name="count" type="number" min="4" max="40" value="8"></label><label>Duração (minutos)<input name="duration" type="number" min="5" max="180" value="30"></label><label>Dificuldade<select name="difficulty">${[1,2,3,4,5].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></label></div><button class="primary" ${d.eligibility.eligible?'':'disabled'}>Iniciar simulação</button></form><p class="small muted">O resultado é uma avaliação interna do Teo, sem equivalência a uma aprovação oficial de concílio.</p></section><section class="panel"><h2>Suas simulações</h2>${d.simulations.length?d.simulations.slice().reverse().map(s=>`<div class="discipline row between"><span>${date(s.createdAt)} · ${s.index}/${s.questionIds.length} respostas</span>${button(s.status==='active'?'Retomar':'Ver relatório','open-simulation',`data-id="${s.id}"`)}</div>`).join(''):empty('A preparação deixa um histórico','Suas simulações e relatórios aparecerão aqui.')}</section></div>`;}
function simulationView(){const sim=state.simulation;if(sim.status==='active')return `${intro('BANCA TEXTUAL',`Pergunta ${sim.index+1} de ${sim.questionIds.length}`,'Responda de forma clara, com suas convicções e fundamentação pertinente.')}<div class="panel"><p class="small muted">Limite da sessão: ${new Date(sim.deadline).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</p><p class="sim-question">${esc(sim.question.text)}</p><form id="simulation-answer"><label>Sua resposta<textarea name="answer" required minlength="5" maxlength="15000"></textarea></label><button class="primary">Registrar e continuar</button></form>${button('Finalizar agora','finish-simulation','class="quiet"')}</div>`;
  const attempts=state.data.attempts.filter(a=>a.simulationId===sim.id),graded=attempts.filter(a=>a.score!==null),avg=graded.length?graded.reduce((sum,a)=>sum+a.score,0)/graded.length:null;
  return `${intro('RELATÓRIO DA SIMULAÇÃO','Convicções em desenvolvimento.','Avaliação interna do Teo. Este resultado não constitui aprovação oficial de concílio.')}<div class="panel"><div class="row between"><span class="metric">${avg===null?'-':avg.toFixed(1)}<small> / 10</small></span>${badge(graded.length<sim.questionIds.length?'Avaliação incompleta':avg>=7?'Preparação satisfatéria':avg>=5?'Preparação em desenvolvimento':'Necessita de reforço',avg>=7)}</div><p>${graded.length} de ${sim.questionIds.length} respostas avaliadas.</p>${state.data.axes.map(axis=>{const a=graded.filter(x=>x.axisId===axis.id);return `<div class="chart-row row between"><span>${esc(axis.title)}</span><strong>${a.length?(a.reduce((sum,x)=>sum+x.score,0)/a.length).toFixed(1)+'/10':'Sem nota'}</strong></div>`;}).join('')}${attempts.map(a=>`<div class="discipline"><h3>${esc(state.data.questions.find(q=>q.id===a.questionId)?.text||'Pergunta registrada')}</h3><p>${esc(a.answer)}</p>${a.feedback?feedback(a):button('Avaliar resposta com IA','evaluate-attempt',`data-id="${a.id}"`)}</div>`).join('')}${button('Voltar às avaliações','close-simulation')}</div>`;
}
function library(){const docs=state.data.documents;return `${intro('FONTES QUE SUSTENTAM O ESTUDO','Sua biblioteca teológica.','Documentos autorizados, com páginas preservadas e processamento validado antes de fundamentarem respostas.')}<form id="search-form" class="row"><input name="q" required minlength="3" placeholder="Busque um conceito, uma doutrina ou uma passagem." aria-label="Busca na biblioteca" style="flex:1;min-width:220px"><button class="primary">Pesquisar</button></form><div id="search-results"></div><div class="section-head"><h2>Documentos</h2>${state.data.user.role==='admin'?button('Adicionar PDF','upload-document'):''}</div><div class="grid three">${docs.map(d=>`<section class="panel document-card"><img class="document-thumb" src="/api/documents/${d.id}/thumbnail" alt="Capa de ${esc(d.title)}" loading="lazy" onerror="this.remove()"><div class="eyebrow">${esc(d.category)}</div><h2 style="font-size:1.6rem">${esc(d.title)}</h2><p class="muted small">${esc(d.author||'Autor não informado')}${d.edition?' · '+esc(d.edition):''}</p><div class="row">${badge(statuses[d.status]||d.status,d.status==='validated')}${badge(d.indexStatus==='semantic_ready'?'Busca semântica':d.indexStatus==='text_ready'?'Busca textual':'Indexação pendente')}</div><p class="small muted">${d.pages||'-'} páginas · ${d.shared?'Compartilhado com contas autorizadas':'Documento privado'}</p>${button('Abrir documento','open-document',`data-id="${d.id}"`)}${button(state.data.favorites.some(f=>f.targetId===d.id)?'?':'?','favorite',`data-id="${d.id}" data-kind="document" aria-label="Alternar favorito" class="quiet"`)}</section>`).join('')||`<div class="panel" style="grid-column:1/-1">${empty('Uma biblioteca construída com cuidado','Carregue suas cópias autorizadas de Langston, dos documentos batistas e da Confissão de 1689. Nenhuma obra vem incluída automaticamente.')}</div>`}</div>`;}
function sourceList(sources){return sources.map(s=>`<div class="source"><button class="link" data-action="open-source" data-id="${esc(s.documentId)}" data-page="${Number(s.page)}">${esc(s.document)} · p. ${Number(s.page)}${s.section?' · '+esc(s.section):''}</button><blockquote>${esc(s.text)}</blockquote></div>`).join('');}
function preferenceForm(id='profile-form'){const d=state.data,p=d.profile,pref=d.preferences||{};return `<form id="${id}"><div class="form-grid"><label>Nome<input name="name" required value="${esc(p.name)}" maxlength="120"></label><label>Conhecimento teológico<select name="level">${['iniciante','básico','intermediário','avançado'].map(v=>`<option ${p.level===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Formação<select name="formation">${['Autodidata','Curso livre','Seminário','Graduação','Outra'].map(v=>`<option ${p.formation===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Tempo diário<select name="minutes">${[15,30,45,60,90].map(v=>`<option value="${v}" ${pref.minutes===v?'selected':''}>${v} minutos</option>`).join('')}</select></label><label>Objetivo<select name="objective">${['Preparação para concílio','Ordenação','Formação geral','Aperfeiçoamento ministerial'].map(v=>`<option ${p.objective===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Data prevista do concílio (opcional)<input name="councilDate" type="date" value="${esc(pref.councilDate||'')}"></label><fieldset class="full"><legend>Dias disponíveis na semana</legend><div class="day-picker">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((v,i)=>`<label><input type="checkbox" name="days" value="${i}" ${(pref.days||[1,2,3,4,5]).includes(i)?'checked':''}>${v}</label>`).join('')}</div></fieldset><p class="small muted full">Tradição eclesiológica inicial: Batista. A autoavaliação será complementada pelo diagnóstico.</p></div><button class="primary">${id==='onboarding-form'?'Salvar e iniciar minha jornada':'Salvar preferências'}</button></form>`;}
function onboarding(){return `${intro('UM PONTO DE PARTIDA PESSOAL','Como será sua preparação?','Sua rotina e seus objetivos ajudam o Teo a organizar uma jornada possível de sustentar.')}<section class="panel" style="max-width:850px">${preferenceForm('onboarding-form')}</section>`;}
function profile(){const d=state.data;return `${intro('APRENDIZAGEM COM PROPÓSITO','Seu perfil e sua rotina.','Ajuste seu ritmo, preserve suas reflexões e mantenha o controle dos seus dados.')}<div class="grid"><section class="panel"><h2>Preferências de estudo</h2>${preferenceForm()}</section><section><div class="panel"><h2>Minha Jornada Ministerial</h2><p class="muted">Seu testemunho, chamado pastoral e experiências, em uma área privada.</p>${button('Abrir minha jornada','navigate','data-route="journey"',true)}</div><div class="panel" style="margin-top:20px"><h2>Conta e privacidade</h2><p class="muted">${esc(d.user.email)}</p><p class="small">A jornada ministerial e as credenciais de IA são criptografadas no servidor. Não inclua dados de terceiros sem necessidade.</p><div class="row">${button('Exportar meus registros','export')}${button('Sair da conta','logout')}${d.user.role==='admin'?button('Administração','navigate','data-route="admin"'):''}</div><hr class="divider">${button('Excluir minha conta','delete-account','class="danger"')}<p class="small muted">A exclusão remove seus registros privados e documentos. Backups externos precisam ser tratados pelo operador.</p></div></section></div>`;}
const journeyFields={testimony:[['conversion','História da conversão'],['gospel','Como conheceu o evangelho'],['experiences','Experiências marcantes'],['walk','Caminhada cristã'],['church','Participação na igreja'],['membership','Membresia'],['salvation','Convicções sobre a salvação']],calling:[['perception','Como percebeu o chamado'],['experiences','Experiências que contribuíram'],['recognition','Reconhecimento da igreja'],['ministry','Experiências ministeriais'],['vocation','Convicções sobre vocação'],['responsibilities','Expectativas e responsabilidades']]};
function journey(){return `${intro('UMA HISTÓRIA QUE TAMBÉM ENSINA','Minha Jornada Ministerial.','Organize sua caminhada e reflita sobre a vocação pastoral. Estes registros pertencem somente à sua experiência privada.')}<div class="notice">O uso desses dados pela IA exige habilitação administrativa e uma escolha explícita na pergunta ao assistente.</div><div id="journey-content" class="panel"><p class="muted">Carregando registros privados.</p></div>`;}
async function loadJourney(){try{const data=await api('/api/journey');state.journey=data;const el=$('#journey-content');if(!el)return;el.innerHTML=`<form id="journey-form"><div class="grid">${Object.entries(journeyFields).map(([section,fields])=>`<section><h2>${section==='testimony'?'Testemunho':'Chamado pastoral'}</h2>${fields.map(([key,label])=>`<label>${label}<textarea name="${section}.${key}" maxlength="10000">${esc(data[section]?.[key]||'')}</textarea></label>`).join('')}</section>`).join('')}</div><p class="saved" id="journey-saved">Salvamento automático após a edição.</p><button class="primary">Salvar agora</button></form><hr class="divider"><h2>Registros complementares</h2><form id="journey-entry-form"><div class="form-grid"><label>Data<input name="date" type="date" required></label><label>Título<input name="title" required maxlength="200"></label><label class="full">Registro<textarea name="text" required></textarea></label></div><button>Adicionar registro</button></form><div class="timeline">${(data.entries||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div><span class="small muted">${date(e.date+'T12:00:00')}</span><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p>${button('Excluir registro','delete-entry',`data-id="${esc(e.id)}" class="quiet danger"`)}</div>`).join('')}</div><hr class="divider"><div class="row">${button('Exportar jornada','export-journey')}${button('Excluir toda a jornada','delete-journey','class="danger"')}</div>`;const form=$('#journey-form');let timer;const savedElement=$('#journey-saved');const save=async()=>{const result={testimony:{},calling:{},entries:state.journey.entries||[]};for(const [key,value]of new FormData(form)){const [section,field]=key.split('.');result[section][field]=value;}savedElement.textContent='Salvando.';try{await api('/api/journey',{method:'POST',data:result});state.journey=result;savedElement.textContent='Salvo às '+new Date().toLocaleTimeString('pt-BR');}catch(e){savedElement.textContent='Não salvo: '+e.message;}};state.flushJourney=async()=>{clearTimeout(timer);await save();};form.oninput=()=>{clearTimeout(timer);$('#journey-saved').textContent='Alterações pendentes.';timer=setTimeout(save,1000);};form.onsubmit=e=>{e.preventDefault();clearTimeout(timer);save();};$('#journey-entry-form').onsubmit=async e=>{e.preventDefault();state.journey.entries??=[];state.journey.entries.push({id:crypto.randomUUID(),...Object.fromEntries(new FormData(e.currentTarget))});await api('/api/journey',{method:'POST',data:state.journey});await loadJourney();};}catch(e){toast(e.message,true);}}

function options(rows,selected){return rows.map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.title)}</option>`).join('');}
function admin(){const d=state.data;if(!d.admin)return empty('Acesso restrito','Esta área é exclusiva da administração.');const tab=state.adminTab||'content';return `${intro('CURADORIA, COM CRITÉRIO','Administração do Teo.','Fontes confiáveis, revisão humana e publicação consciente sustentam o currículo.')}<div class="tabs">${[['content','Conteúdo'],['curriculum','Currículo'],['documents','Documentos'],['questions','Questões'],['ai','Inteligência artificial'],['rules','Critérios'],['audit','Histórico']].map(([id,label])=>button(label,'admin-tab',`data-id="${id}" class="${tab===id?'active':''}"`)).join('')}</div>${adminSection(tab)}`;}
function adminSection(tab){const d=state.data;
  if(tab==='content')return `<div class="row between"><p class="muted">${d.lessons.length} materiais · revisão obrigatéria antes da publicação</p><div class="row">${button('Gerar com IA','generate-content')}${button('Criar material de estudo','edit-lesson','',true)}</div></div><div class="panel">${d.lessons.length?`<div class="row">${button('Publicar aprovados selecionados','publish-batch')}</div><ul class="list">${d.lessons.map(l=>`<li><div class="row between"><div class="row"><input type="checkbox" class="batch-lesson" value="${l.id}" aria-label="Selecionar ${esc(l.title)}"><div><h3>${esc(l.title)}</h3><span class="small muted">${esc(d.disciplines.find(x=>x.id===l.disciplineId)?.title)} · v${l.version} · ${l.origin==='ai'?'Origem IA':'Autoria administrativa'}</span></div></div>${badge(statuses[l.status],l.status==='published')}</div><div class="row" style="margin-top:14px">${button('Editar','edit-lesson',`data-id="${l.id}"`)}${button('Versões','lesson-versions',`data-id="${l.id}"`)}${transitionButtons(l)}</div></li>`).join('')}</ul>`:empty('O currículo aguarda as primeiras materiais de estudo','Crie uma material de estudo a partir de fontes autorizadas ou gere um rascunho com a IA conectada.')}</div>`;
  if(tab==='curriculum')return `<div class="grid"><section class="panel"><h2>Organização curricular</h2><form id="curriculum-form"><label>Tipo<select name="table"><option value="disciplines">Disciplina</option><option value="modules">Módulo</option><option value="curriculum">Eixo</option></select></label><label>Título<input name="title" required maxlength="180"></label><label>Eixo<select name="axisId">${options(d.axes)}</select></label><label>Disciplina (para módulo)<select name="disciplineId">${options(d.disciplines)}</select></label><button class="primary">Adicionar ao currículo</button></form></section><section class="panel"><h2>Módulos disponíveis</h2>${d.modules.length?d.modules.map(m=>`<div class="discipline"><h3>${esc(m.title)}</h3><p class="small muted">${esc(d.disciplines.find(x=>x.id===m.disciplineId)?.title)}</p>${button('Editar','edit-curriculum',`data-table="modules" data-id="${m.id}"`)}</div>`).join(''):empty('Adicione os módulos de estudo','Os módulos ligam cada disciplina aos materiais de estudo.')}<details><summary>Editar eixos e disciplinas</summary>${[...d.axes.map(x=>({...x,table:'curriculum'})),...d.disciplines.map(x=>({...x,table:'disciplines'}))].map(x=>`<div class="row between discipline"><span>${esc(x.title)}</span>${button('Editar','edit-curriculum',`data-table="${x.table}" data-id="${x.id}"`)}</div>`).join('')}</details></section></div>`;
  if(tab==='documents')return `<div class="row between"><p class="muted">Confira a extração e as páginas antes de validar.</p>${button('Enviar PDF','upload-document','',true)}</div><div class="panel">${d.documents.length?d.documents.map(doc=>`<section class="discipline"><div class="row between"><h3>${esc(doc.title)}</h3>${badge(statuses[doc.status]||doc.status,doc.status==='validated')}</div><p class="small muted">${esc(doc.error||doc.extractionOrigin||'PDF recebido com controle de disponibilidade.')} ${esc((doc.extractionWarnings||[]).join(' '))}</p><div class="row">${button('Conferir PDF e extração','open-document',`data-id="${doc.id}"`)}${button('Processar / reprocessar','process-document',`data-id="${doc.id}"`)}${button('Importar páginas','import-pages',`data-id="${doc.id}"`)}${doc.status==='extracted'?button('Validar extração','validate-document',`data-id="${doc.id}"`):''}${doc.status==='validated'?button('Indexar semanticamente','index-document',`data-id="${doc.id}"`):''}${button('Remover','delete-document',`data-id="${doc.id}" class="danger"`)}</div></section>`).join(''):empty('Nenhum documento recebido','Envie arquivos PDF com as permissões de uso correspondentes.')}</div>`;
  if(tab==='questions')return `<div class="row between"><p class="muted">Perguntas reais preservam a formulação e a origem informadas.</p><div class="row">${button('Importar JSON','import-questions')}${button('Criar pergunta','edit-question','',true)}</div></div><div class="panel">${d.admin.questions.length?d.admin.questions.map(q=>`<div class="discipline"><div class="row between"><h3>${esc(q.text)}</h3>${badge(statuses[q.status],q.status==='published')}</div><p class="small muted">${q.origin==='real'?'Real · '+esc(q.source):'Complementar'} · ${esc(q.type)} · ${esc(d.disciplines.find(x=>x.id===q.disciplineId)?.title)}</p><div class="row">${button('Editar','edit-question',`data-id="${q.id}"`)}${q.status==='draft'?button('Aprovar','question-status',`data-id="${q.id}" data-status="approved"`):''}${q.status==='approved'?button('Publicar','question-status',`data-id="${q.id}" data-status="published"`):''}${q.status==='published'?button('Arquivar','question-status',`data-id="${q.id}" data-status="archived"`):''}</div></div>`).join(''):empty('Banco ainda vazio','Crie questões ou importe uma lista. Questões geradas não são classificadas como reais.')}</div>`;
  if(tab==='ai'){const a=d.admin.ai,calls=d.admin.usage,day=new Date().toISOString().slice(0,10),today=calls.filter(x=>x.createdAt.startsWith(day)).length;return `<div class="notice"><strong>Prioridade: sua assinatura ChatGPT.</strong> Execute <code>npm run ai:connect</code> no servidor e autorize no navegador desse computador. Este fluxo usa OAuth oficial; não solicita sua senha nem reutiliza cookies. Conexão ainda depende de autorização e elegibilidade da conta. Para um serviço comercial remoto, verifique a aprovação de integração.</div><div class="grid"><section class="panel"><h2>Provedor e limites</h2><form id="ai-form"><label>Provedor ativo<select name="provider">${[['none','Sem IA'],['chatgpt','ChatGPT - franquia da assinatura'],['ollama','Ollama local'],['openai','OpenAI - API com cobrança separada'],['compatible','API compatével']].map(([v,n])=>`<option value="${v}" ${a.provider===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Modelo<input name="model" value="${esc(a.model)}" list="ai-models" maxlength="150"><datalist id="ai-models"></datalist></label>${button('Consultar modelos da assinatura','load-models')}<label>Endpoint (outros provedores)<input name="endpoint" type="url" value="${esc(a.endpoint)}" placeholder="http://127.0.0.1:11434"></label><label>Chave (apenas APIs; nunca exibida após salvar)<input name="key" type="password" autocomplete="new-password"></label><div class="form-grid"><label>Chamadas/dia<input name="dailyCalls" type="number" min="1" value="${a.dailyCalls}"></label><label>Chamadas/mês<input name="monthlyCalls" type="number" min="1" value="${a.monthlyCalls}"></label><label>Limite de saída (APIs)<input name="maxTokens" type="number" min="100" value="${a.maxTokens}"></label><label>Temperatura (APIs)<input name="temperature" type="number" min="0" max="2" step="0.1" value="${a.temperature}"></label><label>US$/1M tokens entrada<input name="inputPrice" type="number" min="0" step="0.001" value="${a.inputPrice}"></label><label>US$/1M tokens saída<input name="outputPrice" type="number" min="0" step="0.001" value="${a.outputPrice}"></label></div><p class="small muted">A assinatura controla seus próprios limites e não aceita todos os parâmetros da API comum. O Teo não fará troca automática para uma API paga.</p><fieldset><legend>Recursos habilitados</legend>${[['tutor','Assistente'],['generate','Geração de materiais de estudo'],['evaluate','Avaliação discursiva']].map(([key,label])=>`<label class="check"><input type="checkbox" name="enabledFeatures" value="${key}" ${a.enabledFeatures.includes(key)?'checked':''}>${label}</label>`).join('')}</fieldset><label class="check"><input type="checkbox" name="allowPersonalJourney" ${a.allowPersonalJourney?'checked':''}>Permitir envio opcional da jornada privada à IA</label><h3 style="margin-top:25px">Embeddings locais para busca semântica</h3><label>Modelo de embeddings<input name="embeddingModel" value="${esc(a.embeddingModel)}"></label><label>Endpoint Ollama<input name="embeddingEndpoint" type="url" value="${esc(a.embeddingEndpoint)}"></label><div class="row" style="margin-top:20px"><button class="primary">Salvar configuração</button>${button('Testar conexão (uma chamada)','test-ai')}</div></form></section><section><div class="panel"><h2>Consumo registrado</h2><div class="metric">${today}<small> / ${a.dailyCalls} hoje</small></div><p class="muted">${calls.length} chamadas registradas para esta conta.</p>${today>=a.dailyCalls*.8?'<div class="notice">Você atingiu pelo menos 80% do limite diário configurado.</div>':''}<p class="small">Assinatura: consumo da franquia autorizada; custo incremental não é estimado por tokens.</p><p class="small muted">Credenciais conectadas: ${esc(d.ai.connected.join(', ')||'nenhuma')}</p></div><div class="panel" style="margin-top:20px"><h2>Últimas chamadas</h2><div class="table-scroll"><table><thead><tr><th>Recurso</th><th>Estado</th><th>Tokens</th><th>Estimativa US$</th></tr></thead><tbody>${calls.slice(-20).reverse().map(c=>`<tr><td>${esc(c.feature)}</td><td>${esc(c.status)}</td><td>${c.inputTokens??'-'} / ${c.outputTokens??'-'}</td><td>${c.estimatedCost===null?'-':c.estimatedCost?.toFixed(6)}</td></tr>`).join('')}</tbody></table></div></div></section></div>`;}
  if(tab==='rules'){const r=d.admin.rules;return `<section class="panel" style="max-width:700px"><h2>Critérios de preparação</h2><form id="rules-form"><label>Nota mínima nas atividades essenciais<input type="number" name="minimumScore" min="0" max="10" step="0.1" value="${r.minimumScore}"></label><label>Domínio mínimo por disciplina<input type="number" name="requiredMastery" min="0" max="10" step="0.1" value="${r.requiredMastery}"></label><label>Tempo ativo mínimo por material de estudo (segundos)<input type="number" name="minimumActiveSeconds" min="10" max="3600" value="${r.minimumActiveSeconds}"></label><label class="check"><input type="checkbox" name="requireRealQuestions" ${r.requireRealQuestions?'checked':''}>Exigir perguntas reais para liberar a simulação</label><label class="check"><input type="checkbox" name="publicSignup" ${r.publicSignup?'checked':''}>Habilitar cadastro público</label><button class="primary">Salvar critérios</button></form><div class="notice">A data estimada não libera a simulação. A conclusão, as avaliações, o domínio e a cobertura do banco determinam a liberação.</div></section>`;}
  if(tab==='audit')return `<div class="panel"><h2>Revisões e ações administrativas</h2><ul class="list">${[...d.admin.audit].reverse().map(a=>`<li><strong>${esc(a.action)}</strong><p class="small muted">${date(a.createdAt)} · ${esc(a.targetId)}</p></li>`).join('')||'<li>Nenhuma ação registrada.</li>'}</ul><h2 style="margin-top:30px">Fila de revisão</h2>${d.admin.reviews.slice().reverse().map(r=>`<p class="small">${esc(r.from)}  ${esc(r.to)} · ${esc(r.comment)} · ${date(r.createdAt)}</p>`).join('')}</div>`;
}
function transitionButtons(l){const transitions={draft:[['pending_review','Enviar para revisão']],ai_generated:[['pending_review','Enviar para revisão']],pending_review:[['in_review','Iniciar revisão'],['needs_changes','Solicitar ajustes'],['rejected','Reprovar']],in_review:[['approved','Aprovar'],['needs_changes','Solicitar ajustes'],['rejected','Reprovar']],needs_changes:[['pending_review','Reenviar para revisão']],rejected:[['draft','Reabrir rascunho']],approved:[['published','Publicar']],published:[['archived','Arquivar']],archived:[['draft','Reabrir rascunho']]};return (transitions[l.status]||[]).map(([status,label])=>button(label,'lesson-status',`data-id="${l.id}" data-status="${status}"`)).join('');}
function modal(title,html){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${esc(title)}</h2>${button('Fechar','close-modal','class="quiet"')}</header>${html}</section></div>`;const target=$('#overlay input, #overlay textarea, #overlay button');target?.focus();}
function closeModal(){$('#overlay').innerHTML='';}
function confirmAction(title,text,action){return new Promise(resolve=>{modal(title,`<p>${esc(text)}</p><div class="row"><button class="danger" id="confirm-yes">${esc(action)}</button><button id="confirm-no">Cancelar</button></div>`);$('#confirm-yes').onclick=()=>{closeModal();resolve(true);};$('#confirm-no').onclick=()=>{closeModal();resolve(false);};state.pendingConfirm=resolve;});}
function lessonEditor(id){const d=state.data,l=d.lessons.find(x=>x.id===id)||{};modal(id?'Editar material de estudo':'Nova material de estudo',`<form id="lesson-editor"><input type="hidden" name="id" value="${esc(l.id||'')}"><label>Título<input name="title" required value="${esc(l.title)}" maxlength="180"></label><div class="form-grid"><label>Disciplina<select name="disciplineId">${options(d.disciplines,l.disciplineId)}</select></label><label>Módulo<select name="moduleId"><option value="">Selecione um módulo</option>${options(d.modules,l.moduleId)}</select></label><label>Duração estimada (minutos)<input type="number" name="estimatedMinutes" min="5" max="240" value="${l.estimatedMinutes||30}"></label><label class="check"><input type="checkbox" name="required" ${l.required!==false?'checked':''}>Material de estudo obrigatéria</label></div><label>Introdução<textarea name="introduction">${esc(l.introduction)}</textarea></label><label>Objetivos (um por linha)<textarea name="objectives">${esc((l.objectives||[]).join('\n'))}</textarea></label><label>Desenvolvimento em tópicos (JSON)<textarea name="topics" class="code">${esc(JSON.stringify(l.topics||[{title:'',text:''}],null,2))}</textarea></label><label>Referências bíblicas (uma por linha)<textarea name="biblicalReferences">${esc((l.biblicalReferences||[]).join('\n'))}</textarea></label>${[['context','Contextualização das passagens'],['doctrinalRelation','Relação entre texto e doutrina'],['conclusion','Conclusão'],['activity','Atividade discursiva (opcional)']].map(([key,label])=>`<label>${label}<textarea name="${key}">${esc(l[key])}</textarea></label>`).join('')}<label>Perguntas de fixação (uma por linha)<textarea name="fixation">${esc((l.fixation||[]).join('\n'))}</textarea></label><label>IDs dos fragmentos autorizados (um por linha)<textarea name="sourceIds">${esc((l.sourceIds||[]).join('\n'))}</textarea></label><p class="small muted">Encontre os IDs conferindo a extração dos documentos. Salvar uma edição retorna o material ao rascunho e exige nova aprovação.</p><button class="primary">Salvar rascunho</button></form>`);$('#lesson-editor').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button');btn.disabled=true;try{const fd=new FormData(e.currentTarget),data=Object.fromEntries(fd);for(const key of ['objectives','biblicalReferences','fixation','sourceIds'])data[key]=data[key].split('\n').map(s=>s.trim()).filter(Boolean);data.topics=JSON.parse(data.topics);data.required=fd.has('required');if(!data.id)delete data.id;await api('/api/admin/lessons',{method:'POST',data});closeModal();await refresh('Rascunho salvo.');}catch(e){toast(e.message,true);}finally{btn.disabled=false;}};}
function questionEditor(id){const d=state.data,q=d.admin.questions.find(q=>q.id===id)||{};modal(id?'Editar questão':'Nova questão',`<form id="question-editor"><input type="hidden" name="id" value="${esc(q.id||'')}"><label>Texto original da pergunta<textarea name="text" required>${esc(q.text)}</textarea></label><div class="form-grid"><label>Disciplina<select name="disciplineId">${options(d.disciplines,q.disciplineId)}</select></label><label>Material de estudo vinculada<select name="lessonId"><option value="">Sem vínculo</option>${options(d.lessons,q.lessonId)}</select></label><label>Tipo<select name="type">${[['objective','Objetiva'],['true_false','Verdadeiro ou falso'],['matching','Associação'],['discursive','Discursiva']].map(([v,label])=>`<option value="${v}" ${q.type===v?'selected':''}>${label}</option>`).join('')}</select></label><label>Origem<select name="origin"><option value="complementary">Complementar</option><option value="real" ${q.origin==='real'?'selected':''}>Pergunta real fornecida</option></select></label><label>Dificuldade<input type="number" name="difficulty" min="1" max="5" value="${q.difficulty||1}"></label><label>Origem documental da pergunta<input name="source" value="${esc(q.source)}"></label></div><label>Alternativas (uma por linha; objetivas)<textarea name="options">${esc((q.options||[]).join('\n'))}</textarea></label><label>Gabarito (texto exato da alternativa; true/false; JSON para associação)<textarea name="correct">${esc(typeof q.correct==='object'?JSON.stringify(q.correct):q.correct)}</textarea></label><label>Explicação da resposta<textarea name="explanation">${esc(q.explanation)}</textarea></label><label>Referências (uma por linha)<textarea name="references">${esc((q.references||[]).join('\n'))}</textarea></label><label class="check"><input type="checkbox" name="bibleRequired" ${q.bibleRequired!==false?'checked':''}>Exigir fundamentação bíblica</label><p class="small muted">Desmarque quando não couber, como testemunho, chamado ou perguntas históricas.</p><label class="check"><input type="checkbox" name="essential" ${q.essential?'checked':''}>Atividade essencial</label><button class="primary">Salvar para revisão</button></form>`);$('#question-editor').onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.currentTarget),data=Object.fromEntries(fd);data.options=data.options.split('\n').filter(Boolean);data.references=data.references.split('\n').filter(Boolean);data.bibleRequired=fd.has('bibleRequired');data.essential=fd.has('essential');if(data.type==='discursive')delete data.correct;if(data.type==='matching')data.correct=JSON.parse(data.correct);if(!data.id)delete data.id;if(!data.lessonId)delete data.lessonId;await api('/api/admin/questions',{method:'POST',data});closeModal();await refresh('Questão salva em rascunho.');}catch(err){toast(err.message,true);}};}
function uploadDocument(){modal('Adicionar documento autorizado',`<form id="upload-form"><label>PDF (até 100 MB)<input type="file" name="file" accept="application/pdf" required></label><label>Título<input name="title" required maxlength="250"></label><div class="form-grid"><label>Autor<input name="author"></label><label>Edição<input name="edition"></label><label>Categoria<input name="category" value="Teologia"></label><label>Permissão ou licença<input name="license" value="Uso privado autorizado" required></label></div><label>Descrição<textarea name="description"></textarea></label><label class="check"><input name="licenseConfirmed" type="checkbox" required>Tenho autorização ou licença adequada para este uso.</label><label class="check"><input name="shared" type="checkbox">Disponibilizar a outras contas autorizadas após validação</label><button class="primary">Enviar documento</button></form>`);$('#upload-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button');btn.disabled=true;try{const fd=new FormData(form),file=fd.get('file');if(file.size>100*1024*1024)throw new Error('Limite de 20 MB.');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});const data=Object.fromEntries(fd);delete data.file;data.base64=base64;data.licenseConfirmed=fd.has('licenseConfirmed');data.shared=fd.has('shared');await api('/api/admin/documents',{method:'POST',data});closeModal();await refresh('PDF recebido. Processe e valide a extração.');}catch(err){toast(err.message,true);}finally{btn.disabled=false;}};}
async function openDocument(id,page=1){const d=await api('/api/documents/'+id);modal(d.title,`${state.data.user.role==='admin'?button('Editar metadados','document-metadata',`data-id="${id}"`):''}<div class="preview-grid"><div><iframe src="/api/documents/${id}/file#page=${Number(page)||1}" title="PDF: ${esc(d.title)}"></iframe><a href="/api/documents/${id}/file#page=${Number(page)||1}" target="_blank" rel="noopener">Abrir leitor em nova janela</a></div><div><h3>Extração por página</h3><p class="small muted">Confira o texto com o PDF original antes de validar. IDs dos fragmentos podem ser usados nas fontes das materiais de estudo.</p>${d.chunks?.length?d.chunks.map(c=>`<details class="discipline" ${c.page===Number(page)?'open':''}><summary>Página ${c.page} · ${esc(c.section||'fragmento')}</summary><p class="small muted">ID: ${esc(c.id)}</p><p style="white-space:pre-wrap">${esc(c.text)}</p></details>`).join(''):empty('Extração ainda indisponível','Use Processar documento na administração.')}</div></div>`);}
function assistant(){if(state.assistant){state.assistant=false;$('.drawer')?.remove();return;}state.assistant=true;const el=document.createElement('aside');el.className='drawer';el.setAttribute('role','dialog');el.setAttribute('aria-label','Assistente Teo');el.innerHTML=`<header><div><div class="brand"><img src="/icon.svg" alt=""><strong>teo.</strong></div><p class="small muted">${state.lessonId?'Ao lado da sua leitura':'Seu assistente de estudo'}</p></div>${button('Fechar','assistant','class="quiet"')}</header><div class="drawer-body" id="chat-messages"><p class="muted small">Pergunte sobre um conceito ou trecho. As fontes serão exibidas quando houver respaldo nos documentos autorizados.</p></div><form id="assistant-form"><label for="assistant-question">Sua pergunta</label><textarea id="assistant-question" name="question" required maxlength="5000"></textarea>${state.data.admin?.ai.allowPersonalJourney?'<label class="check"><input type="checkbox" name="usePersonalJourney">Incluir minha jornada privada nesta pergunta</label>':''}<button class="primary" style="width:100%;margin-top:10px">Perguntar</button></form>`;document.body.appendChild(el);$('#assistant-question').value=state.selectedText?'Explique este trecho: '+state.selectedText:'';$('#assistant-question').focus();$('#assistant-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button'),fd=new FormData(form);btn.disabled=true;const old=$('#chat-loading');if(old){old.previousElementSibling?.remove();old.remove();}const question=fd.get('question');$('#chat-messages').insertAdjacentHTML('beforeend',`<div class="message question-msg">${esc(question)}</div><p class="small muted" id="chat-loading">Consultando fontes e preparando resposta.</p>`);try{const result=await api('/api/assistant',{method:'POST',data:{question,lessonId:state.lessonId,usePersonalJourney:fd.has('usePersonalJourney')}});$('#chat-loading')?.remove();$('#chat-messages').insertAdjacentHTML('beforeend',`<div class="message">${esc(result.answer)}</div>${sourceList(result.sources||[])}`);form.reset();btn.textContent='Perguntar';}catch(err){if(form.isConnected){$('#chat-loading').textContent=err.message;btn.textContent='Tentar novamente';}}finally{btn.disabled=false;if($('#chat-messages'))$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}};}
async function refresh(message){await load();render();if(message)toast(message);}
function bindForms(){
  for(const id of ['profile-form','onboarding-form'])if($('#'+id))$('#'+id).onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),data=Object.fromEntries(fd);data.days=fd.getAll('days').map(Number);await submit(e.currentTarget,async()=>{await api('/api/profile',{method:'POST',data});if(id==='onboarding-form')state.route='home';await refresh('Rotina de estudo salva.');});};
  document.querySelectorAll('form[data-question-id]').forEach(form=>{if(form.dataset.diagnostic==='true')return;form.onsubmit=async e=>{e.preventDefault();await submit(form,async()=>{let answer=new FormData(form).get('answer');const q=state.data.questions.find(q=>q.id===form.dataset.questionId);if(q.type==='matching')answer=JSON.parse(answer);const result=await api('/api/questions/answer',{method:'POST',data:{questionId:q.id,answer}});await load();form.querySelector('.answer-feedback').innerHTML=result.score===null?`<div class="feedback">Resposta salva. A nota depende de avaliação por IA.${button('Avaliar agora','evaluate-attempt',`data-id="${result.id}"`)}</div>`:`<div class="feedback"><strong>${result.score}/10</strong><p>${esc(result.explanation||'')}</p><p class="small">Resposta esperada: ${esc(typeof result.correct==='object'?JSON.stringify(result.correct):result.correct)}</p></div>`;toast('Tentativa registrada.');});};});
  if($('#search-form'))$('#search-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const result=await api('/api/library/search?q='+encodeURIComponent(new FormData(e.currentTarget).get('q')));$('#search-results').innerHTML=`<div class="panel" style="margin-top:20px"><p class="small muted">Busca ${result.method==='semantic'?'semântica':'textual'} · ${result.sources.length} fragmentos</p>${sourceList(result.sources)||empty('Nenhum trecho encontrado','Confira os termos e a validação dos documentos.')}</div>`;});};
  if($('#simulation-form'))$('#simulation-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{state.simulation=await api('/api/simulations/start',{method:'POST',data:Object.fromEntries(new FormData(e.currentTarget))});state.simulation=await api('/api/simulations/'+state.simulation.id);render();});};
  if($('#simulation-answer'))$('#simulation-answer').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const result=await api('/api/simulations/answer',{method:'POST',data:{simulationId:state.simulation.id,answer:new FormData(e.currentTarget).get('answer')}});if(state.data.ai.provider!=='none')try{await api('/api/attempts/evaluate',{method:'POST',data:{attemptId:result.attemptId}});}catch(err){toast('Resposta salva; avaliação pendente: '+err.message,true);}await load();state.simulation=await api('/api/simulations/'+state.simulation.id);render();});};
  if($('#curriculum-form'))$('#curriculum-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/admin/curriculum',{method:'POST',data:Object.fromEntries(new FormData(e.currentTarget))});await refresh('Currículo atualizado.');});};
  if($('#ai-form'))$('#ai-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const fd=new FormData(e.currentTarget),ai=Object.fromEntries(fd);ai.enabledFeatures=fd.getAll('enabledFeatures');ai.allowPersonalJourney=fd.has('allowPersonalJourney');await api('/api/admin/settings',{method:'POST',data:{ai}});await refresh('Configuração de IA salva.');});};
  if($('#rules-form'))$('#rules-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const fd=new FormData(e.currentTarget),rules=Object.fromEntries(fd);rules.publicSignup=fd.has('publicSignup');rules.requireRealQuestions=fd.has('requireRealQuestions');await api('/api/admin/settings',{method:'POST',data:{rules}});await refresh('Critérios atualizados.');});};
}
async function submit(form,fn){const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{await fn();}catch(err){toast(err.message,true);}finally{if(button)button.disabled=false;}}
let heartbeatTimer,lastInteraction=Date.now(),readingSession=null;
for(const event of ['pointerdown','keydown','scroll','touchmove'])document.addEventListener(event,()=>{lastInteraction=Date.now();},{passive:true});
function bindReading(){clearInterval(heartbeatTimer);const article=$('#lesson-text');article?.style.setProperty('--reading-size',(Number(localStorage.getItem('teo-font'))||20)+'px');const old=state.data.progress.find(p=>p.lessonId===state.lessonId);if(old?.position&&!state.skipRestore){requestAnimationFrame(()=>window.scrollTo(0,old.position*Math.max(1,document.documentElement.scrollHeight-innerHeight)));}state.skipRestore=false;if(!state.session)return;heartbeatTimer=setInterval(async()=>{if(state.route!=='study'||!state.lessonId){clearInterval(heartbeatTimer);return;}const active=!document.hidden&&Date.now()-lastInteraction<60000;try{const result=await api('/api/study/heartbeat',{method:'POST',data:{sessionId:state.session.id,active,interacted:Date.now()-lastInteraction<30000,position:Math.min(1,window.scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight))}});if($('#study-clock'))$('#study-clock').textContent=`${Math.floor(result.activeSeconds)} segundos de leitura ativa nesta sessão${active?'':' · pausada'}`;}catch(e){if($('#study-clock'))$('#study-clock').textContent='Não sincronizado: '+e.message;}},15000);}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();if(state.assistant)assistant();}});
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
  if(el.tagName==='BUTTON'&&el.closest('form'))el.type='button';
  try {
    if(action==='guided-open') return await openGuidedPage(el.dataset.id);
    if(action==='guided-listen'){
      speechSynthesis.cancel();
      const speech = new SpeechSynthesisUtterance($('#guided-text').innerText);
      speech.lang='pt-BR';
      speechSynthesis.speak(speech);
      return;
    }
    if(action==='guided-save'){
      el.disabled=true;
      await api('/api/actions?route=study/guided',{method:'POST',data:{documentId:el.dataset.id,page:Number(el.dataset.page),complete:true}});
      window.speechSynthesis?.cancel();
      closeModal();
      await refresh('Posição salva.');
      return await guidedRecall(el.dataset.id,Number(el.dataset.page));
    }
    if(action==='page-recall') return await guidedRecall(el.dataset.id,Number(el.dataset.page));
    if(action==='record-recall'){
      const field=$('#guided-answer');
      if(!field.value.trim()){field.focus();toast('Escreva sua resposta antes de salvar.',true);return;}
      el.disabled=true;
      const result=await api('/api/actions?route=study/guided',{method:'POST',data:{mode:'recall',documentId:el.dataset.id,page:Number(el.dataset.page),result:el.dataset.result,answer:field.value}});
      closeModal();return await refresh('Resposta salva. Próxima revisão em '+date(result.dueAt)+'.');
    }
    if(action==='guided-reviews'){state.assessmentTab='reviews';state.route='assessments';render();window.scrollTo(0,0);return;}
    if(action==='close-modal' && $('#guided-text'))window.speechSynthesis?.cancel();
    if(action==='retry')return init();
    if(action==='auth-mode')return renderAuth(state.auth,el.dataset.mode);
    if(action==='theme'){document.body.classList.toggle('dark');localStorage.setItem('teo-theme',document.body.classList.contains('dark')?'dark':'light');if(state.data)render();return;}
    if(action==='close-modal'){state.pendingConfirm?.(false);state.pendingConfirm=null;return closeModal();}
    if(action==='navigate'){if(state.flushJourney){await state.flushJourney();state.flushJourney=null;}clearInterval(heartbeatTimer);if(state.assistant)assistant();state.route=el.dataset.route;state.lessonId=null;state.readingMode=false;state.run=null;state.simulation=null;render();window.scrollTo(0,0);return;}
    if(action==='axis'){state.axis=el.dataset.id;return render();}
    if(action==='admin-tab'){state.adminTab=el.dataset.id;return render();}
    if(action==='assessment-tab'){state.assessmentTab=el.dataset.id;return render();}
    if(action==='assistant')return assistant();
    if(action==='open-lesson'){state.lessonId=el.dataset.id;state.route='study';state.session=await api('/api/study/start',{method:'POST',data:{lessonId:state.lessonId}});lastInteraction=Date.now();render();return;}
    if(action==='back-study'){clearInterval(heartbeatTimer);state.lessonId=null;state.readingMode=false;return refresh();}
    if(action==='reading-mode'){state.readingMode=!state.readingMode;state.skipRestore=true;render();return;}
    if(action==='font-larger'||action==='font-smaller'){const size=Math.min(30,Math.max(16,(Number(localStorage.getItem('teo-font'))||20)+(action==='font-larger'?1:-1)));localStorage.setItem('teo-font',size);$('#lesson-text')?.style.setProperty('--reading-size',size+'px');return;}
    if(action==='tts-start'){speechSynthesis.cancel();ttsUtterance=new SpeechSynthesisUtterance($('#lesson-text').innerText);ttsUtterance.lang='pt-BR';ttsUtterance.rate=1;ttsUtterance.pitch=1;const voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang?.toLowerCase().startsWith('pt-br'))||voices.find(v=>v.lang?.toLowerCase().startsWith('pt'));if(voice)ttsUtterance.voice=voice;ttsUtterance.onend=()=>{ttsUtterance=null;toast('Narração concluída.');};ttsUtterance.onerror=()=>toast('Não foi possível narrar este conteúdo.',true);speechSynthesis.speak(ttsUtterance);return;}
    if(action==='tts-pause'){if(speechSynthesis.speaking&&!speechSynthesis.paused){speechSynthesis.pause();toast('Narração pausada.');}return;}
    if(action==='tts-resume'){if(speechSynthesis.paused){speechSynthesis.resume();toast('Narração retomada.');}return;}
    if(action==='tts-stop'){speechSynthesis.cancel();ttsUtterance=null;toast('Narração encerrada.');return;}
    if(action==='annotate'){const quote=window.getSelection()?.toString()||'';state.selectedText=quote;modal('Anotação pessoal',`<form id="note-form">${quote?`<blockquote>${esc(quote)}</blockquote>`:''}<label>Sua reflexão<textarea name="text" required maxlength="20000"></textarea></label><button class="primary">Salvar anotação</button></form>`);$('#note-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/notes',{method:'POST',data:{text:new FormData(e.currentTarget).get('text'),quote,lessonId:state.lessonId}});closeModal();await load();toast('Anotação salva.');});};return;}
    if(action==='favorite'){await api('/api/favorites',{method:'POST',data:{targetId:el.dataset.id,kind:el.dataset.kind}});state.skipRestore=true;return refresh('Favoritos atualizados.');}
    if(action==='delete-note'){if(await confirmAction('Excluir anotação','Esta anotação será removida.','Excluir')){await api('/api/notes/'+el.dataset.id,{method:'DELETE'});await refresh('Anotação removida.');}return;}
    if(action==='complete-study'){await api('/api/study/complete',{method:'POST',data:{sessionId:state.session?.id}});clearInterval(heartbeatTimer);state.lessonId=null;return refresh('Sessão concluída. O domínio continua sendo medido pelas avaliações.');}
    if(action==='start-diagnostic'){state.run=await api('/api/diagnostic/start',{method:'POST',data:{}});state.route='assessments';render();window.scrollTo(0,0);return;}
    if(action==='submit-diagnostic'){const answers={};for(const form of document.querySelectorAll('[data-diagnostic="true"]')){if(!form.reportValidity())return;const q=state.run.questions.find(q=>q.id===form.dataset.questionId);const v=new FormData(form).get('answer');answers[q.id]=q.type==='matching'?JSON.parse(v):v;}await api('/api/diagnostic/submit',{method:'POST',data:{runId:state.run.runId,answers}});state.run=null;state.route='home';return refresh('Diagnóstico concluído. Sua jornada foi recalculada.');}
    if(action==='review-discipline'){state.assessmentTab='practice';state.route='assessments';render();document.querySelector(`[data-question-id="${state.data.questions.find(q=>q.disciplineId===el.dataset.id)?.id}"]`)?.scrollIntoView({behavior:'smooth'});return;}
    if(action==='evaluate-attempt'){el.disabled=true;await api('/api/attempts/evaluate',{method:'POST',data:{attemptId:el.dataset.id}});return refresh('Avaliação salva no histórico.');}
    if(action==='open-simulation'){state.simulation=await api('/api/simulations/'+el.dataset.id);render();return;}
    if(action==='close-simulation'){state.simulation=null;return refresh();}
    if(action==='finish-simulation'){if(await confirmAction('Finalizar simulação','As respostas registradas serão preservadas. Perguntas restantes ficarão sem avaliação.','Finalizar')){await api('/api/simulations/finish',{method:'POST',data:{id:state.simulation.id}});state.simulation=await api('/api/simulations/'+state.simulation.id);await refresh();}return;}
    if(action==='open-document'||action==='open-source')return openDocument(el.dataset.id,Number(el.dataset.page)||1);
    if(action==='source-by-id'){for(const d of state.data.documents){const doc=await api('/api/documents/'+d.id);const chunk=doc.chunks.find(c=>c.id===el.dataset.id);if(chunk)return openDocument(d.id,chunk.page);}throw new Error('Fonte indisponível para esta conta.');}
    if(action==='document-metadata'){const doc=state.data.documents.find(d=>d.id===el.dataset.id);modal('Metadados e disponibilidade',`<form id="metadata-form"><label>Título<input name="title" required value="${esc(doc.title)}"></label><label>Autor<input name="author" value="${esc(doc.author)}"></label><label>Edição<input name="edition" value="${esc(doc.edition)}"></label><label>Categoria<input name="category" value="${esc(doc.category)}"></label><label>Descrição<textarea name="description">${esc(doc.description)}</textarea></label><label class="check"><input type="checkbox" name="shared" ${doc.shared?'checked':''}>Compartilhar como fonte curricular com as contas autorizadas</label><button class="primary">Salvar disponibilidade</button></form>`);$('#metadata-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const fd=new FormData(e.currentTarget);await api('/api/admin/documents/metadata',{method:'POST',data:{...Object.fromEntries(fd),id:doc.id,shared:fd.has('shared')}});closeModal();await refresh('Documento atualizado.');});};return;}
    if(action==='upload-document')return uploadDocument();
    if(action==='process-document'){el.disabled=true;await api('/api/admin/documents/process',{method:'POST',data:{id:el.dataset.id}});return refresh('Extração concluída. Confira as páginas antes de validar.');}
    if(action==='validate-document'){if(await confirmAction('Validar extração','Conferi a paginação, os trechos e as páginas sem texto com o PDF original. Confirmar disponibiliza os fragmentos para recuperação.','Confirmar conferência')){await api('/api/admin/documents/validate',{method:'POST',data:{id:el.dataset.id,confirmed:true}});await refresh('Documento validado.');}return;}
    if(action==='index-document'){el.disabled=true;await api('/api/admin/documents/index',{method:'POST',data:{id:el.dataset.id}});return refresh('Indexação semântica concluída.');}
    if(action==='delete-document'){if(await confirmAction('Remover documento','O PDF e seus fragmentos serão excluídos. Materiais publicados que dependem dele precisam ser arquivadas antes.','Remover')){await api('/api/admin/documents/delete',{method:'POST',data:{id:el.dataset.id}});await refresh('Documento removido.');}return;}
    if(action==='import-pages'){const id=el.dataset.id;modal('Importar extração revisável',`<p class="small muted">Use o número físico da página do PDF. Não atribua texto a uma página sem conferi-lo.</p><form id="pages-form"><label>Lista de páginas (JSON)<textarea name="pages" class="code" required>[{"page":1,"section":"Título da seção","text":"Texto extraído desta página"}]</textarea></label><button class="primary">Importar para conferência</button></form>`);$('#pages-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/admin/documents/pages',{method:'POST',data:{id,pages:JSON.parse(new FormData(e.currentTarget).get('pages'))}});closeModal();await refresh('Páginas importadas; valide a extração após conferir.');});};return;}
    if(action==='edit-lesson')return lessonEditor(el.dataset.id);
    if(action==='edit-question')return questionEditor(el.dataset.id);
    if(action==='lesson-status'){await api('/api/admin/lessons/transition',{method:'POST',data:{ids:[el.dataset.id],status:el.dataset.status}});return refresh('Revisão registrada.');}
    if(action==='publish-batch'){const ids=[...document.querySelectorAll('.batch-lesson:checked')].map(x=>x.value);await api('/api/admin/lessons/transition',{method:'POST',data:{ids,status:'published'}});return refresh('Materiais aprovados publicados.');}
    if(action==='lesson-versions'){const versions=state.data.admin.versions.filter(x=>x.lessonId===el.dataset.id);modal('Histórico de versões',versions.length?versions.slice().reverse().map(v=>`<details class="discipline"><summary>Versão ${v.version} · ${date(v.createdAt)}</summary><pre>${esc(JSON.stringify(v.snapshot,null,2))}</pre></details>`).join(''):empty('Nenhuma versão anterior','As próximas edições e transições serão registradas.'));return;}
    if(action==='question-status'){await api('/api/admin/questions/publish',{method:'POST',data:{id:el.dataset.id,status:el.dataset.status}});return refresh('Status da questão atualizado.');}
    if(action==='import-questions'){modal('Importação de questões',`<p class="small muted">Até 200 por lote. Texto original preservado. Use os IDs de disciplina mostrados no currículo e informe source para perguntas reais.</p><details><summary>Exemplo de estrutura (não será importado automaticamente)</summary><pre>${esc(JSON.stringify([{text:'Insira a pergunta original',disciplineId:'sistematica-1',type:'discursive',origin:'real',source:'Identificação do banco fornecido',difficulty:2,bibleRequired:true,essential:false}],null,2))}</pre></details><form id="questions-import"><label>Lista JSON<textarea name="questions" class="code" required></textarea></label><button class="primary">Importar como rascunhos</button></form>`);$('#questions-import').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/admin/questions',{method:'POST',data:{questions:JSON.parse(new FormData(e.currentTarget).get('questions'))}});closeModal();await refresh('Questões importadas para revisão.');});};return;}
    if(action==='edit-curriculum'){const table=el.dataset.table,row=state.data[table==='curriculum'?'axes':table].find(x=>x.id===el.dataset.id);modal('Editar estrutura',`<p class="small muted">ID: ${esc(row.id)}</p><form id="curriculum-editor"><label>Título<input name="title" required value="${esc(row.title)}"></label><button class="primary">Salvar</button></form>`);$('#curriculum-editor').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/admin/curriculum',{method:'POST',data:{...row,table,title:new FormData(e.currentTarget).get('title')}});closeModal();await refresh('Estrutura atualizada.');});};return;}
    if(action==='generate-content'){modal('Gerar rascunhos com IA',`<p class="small muted">Cada assunto gera uma material de estudo. Os materiais entram como Gerado por IA e precisam de revisão e aprovação individuais.</p><form id="generate-form"><label>Disciplina<select name="disciplineId">${options(state.data.disciplines)}</select></label><label>Módulo<select name="moduleId"><option value="">Selecionar depois</option>${options(state.data.modules)}</select></label><label>Assuntos (um por linha, até 5)<textarea name="subjects" required></textarea></label><button class="primary">Gerar para revisão</button><p id="generate-progress" class="small muted"></p></form>`);$('#generate-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const fd=new FormData(e.currentTarget),subjects=String(fd.get('subjects')).split('\n').filter(x=>x.trim());if(subjects.length>5)throw new Error('Use até 5 assuntos por lote.');for(let i=0;i<subjects.length;i++){$('#generate-progress').textContent=`Gerando ${i+1} de ${subjects.length}.`;await api('/api/admin/generate',{method:'POST',data:{disciplineId:fd.get('disciplineId'),moduleId:fd.get('moduleId')||null,subject:subjects[i]}});}closeModal();await refresh('Rascunhos gerados. Nenhum material foi publicado.');});};return;}
    if(action==='load-models'){el.disabled=true;const result=await api('/api/admin/ai/models');$('#ai-models').innerHTML=result.models.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');toast(`${result.models.length} modelos disponíveis para a conta autorizada.`);return;}
    if(action==='test-ai'){el.disabled=true;const r=await api('/api/admin/ai/test',{method:'POST',data:{}});toast(r.ok?'Conexão verificada.':'O provedor retornou uma resposta inesperada.',!r.ok);return;}
    if(action==='export'){download('teo-meus-registros.json',await api('/api/export'));return;}
    if(action==='export-journey'){download('teo-jornada-ministerial.json',await api('/api/journey'));return;}
    if(action==='delete-entry'){if(await confirmAction('Excluir registro','Esta entrada complementar será removida.','Excluir')){state.journey.entries=state.journey.entries.filter(x=>x.id!==el.dataset.id);await api('/api/journey',{method:'POST',data:state.journey});await loadJourney();}return;}
    if(action==='delete-journey'){if(await confirmAction('Excluir jornada privada','Todos os campos e registros da sua jornada ministerial serão removidos.','Excluir jornada')){await api('/api/journey',{method:'DELETE',data:{}});await loadJourney();}return;}
    if(action==='delete-account'){modal('Excluir minha conta',`<p>Esta ação remove seus registros privados, documentos e credenciais de IA. Conteúdo curricular global criado pela administração permanece no sistema. Confirme sua senha para prosseguir.</p><form id="delete-account-form"><label>Senha atual<input name="password" type="password" required autocomplete="current-password"></label><button class="danger">Excluir definitivamente</button></form>`);$('#delete-account-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/account',{method:'DELETE',data:Object.fromEntries(new FormData(e.currentTarget))});closeModal();state.data=null;state.csrf=null;await init();});};return;}
    if(action==='logout'){if(state.flushJourney){await state.flushJourney();state.flushJourney=null;}await api('/api/auth/logout',{method:'POST',data:{}});state.data=null;state.csrf=null;clearInterval(heartbeatTimer);return init();}
  }catch(err){toast(err.message,true);if(el.isConnected)el.disabled=false;}
  finally{if(el.isConnected)el.disabled=false;}
});
try{if(localStorage.getItem('teo-theme')==='dark')document.body.classList.add('dark');}catch{}
init();

function questionForm(q,diagnostic=false){const prompt=q.text||q.prompt||q.question||'Enunciado não informado';const origin=q.origin||((q.provenanceKind||'').includes('real')?'real':'complementary');return `<form class="question" data-question-id="${q.id}" data-diagnostic="${diagnostic}"><div class="row between">${badge(q.type==='discursive'?'Discursiva':q.type==='matching'?'Associação':'Objetiva')}${badge(origin==='real'?'Questão real':'Complementar')}</div>${q.axisId||q.discipline?`<p class="small muted question-meta">${esc(q.axisId||'')}${q.discipline?` · ${esc(q.discipline)}`:''}</p>`:''}<h3 style="margin-top:15px">${esc(prompt)}</h3>${q.type==='discursive'?'<textarea name="answer" required minlength="5" maxlength="15000" aria-label="Sua resposta"></textarea>':q.type==='matching'?`<label>Associação (JSON)<textarea class="code" name="answer" required placeholder='{"A":"1","B":"2"}'></textarea></label>`:(q.type==='true_false'?['Verdadeiro','Falso']:q.options||[]).map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${esc(q.type==='true_false'?String(i===0):o)}" required><span>${esc(o)}</span></label>`).join('')}${diagnostic?'':`<button class="primary">Salvar resposta</button>`}<div class="answer-feedback" aria-live="polite"></div></form>`;}
